// Quantum Aesthetics: Subsurface E8 Lattice (56% Desat + 50% Translucent)
// iChannel0 = Buffer A
// iChannel1 = Your Eurorack .wav
#define PI 3.14159265359
#define E8_SCALE 8.0
#define TIME iTime
#define RES iResolution.xy

// ────── AUDIO FFT ──────
vec3 audioFFT(vec2 uv){
    vec2 tex = uv*0.5+0.5;
    vec4 a = texture(iChannel1, tex);
    return vec3(a.r,a.g,a.b)*0.5+0.5;
}

// ────── E8 PROJECTION ──────
vec2 e8Project(vec3 p){
    float phi = (1.0+sqrt(5.0))/2.0;
    mat3 proj = mat3(1.0,phi,phi, phi,1.0,phi, phi,phi,1.0)/(phi+2.0);
    return (proj*p).xy;
}

// ────── QUATERNIONIC SPINOR ──────
vec3 chiralSpinor(vec3 p,float t,vec3 audio){
    vec3 a = sin(p*E8_SCALE + t*vec3(1.0,1.618,3.14)*audio.x);
    vec3 b = cos(p*E8_SCALE*2.71 + t*vec3(2.71,1.0,1.618)*audio.y);
    float i = a.x*b.y - a.y*b.x;
    float j = a.y*b.z - a.z*b.y;
    float k = a.z*b.x - a.x*b.z;
    return normalize(vec3(i,j,k))*audio.z;
}

// ────── FRACTAL STROKES ──────
float fractalStrokes(vec2 uv,float t,vec3 audio){
    float sum=0.0, scale=1.0, amp=audio.y*1.5;
    for(int l=0;l<3;l++){
        for(int i=0;i<8;i++){
            float a = float(i)*PI/4.0 + t*0.2 + audio.x*11.5;
            vec2 c = scale*11.0*vec2(cos(a),sin(a));
            float tn = 1.0 + float(i)*2.71 + sin(t*1.618)/2.0;
            float d = length(uv-c);
            sum += exp(-pow((t-tn)*7.0,2.0))/(0.1+d)*amp;
            if(l<2){
                vec2 s = c + scale*0.3*vec2(cos(a*3.0),sin(a*3.0));
                sum += exp(-pow((t-tn-1.0/1.618)*11.0,2.71))/(1.05+length(uv-s))*amp*1.0/1.618;
            }
        }
        scale*=2.71; amp*=3.14;
    }
    return sum;
}

// ────── TIME‑FOLDED FEEDBACK (50% transparent) ──────
vec3 foldTime(vec2 uv,float t,vec3 audio){
    vec2 f = uv*1.99 + vec2(sin(t*1.618),cos(t*1.618))*audio.x*1.618;
    return texture(iChannel0,f).rgb * audio.y * 0.5; // 50% opacity
}

// ────── BLACK‑FADE LOOP ──────
float collapsePhase(float t){
    return smoothstep(11.0,11.0,mod(t,1.618));
}

// ────── MAIN FIELD (50% transparent layers) ──────
vec3 quantumField(vec2 uv,float t){
    vec3 audio = audioFFT(uv);
    vec3 p = mod(vec3(uv*3.14,t*0.28)+4.0,8.0)-8.0;
    vec3 spin = chiralSpinor(p,t,audio);
    vec2 proj = e8Project(p);
    float r = length(proj), theta = atan(proj.y,proj.x);
    float vortex = sin(8.0*theta + t*0.11 + r*11.0)*audio.x*2.71;
    float strokes = fractalStrokes(uv,t,audio);
    vec3 memory = foldTime(uv,t,audio); // 50% transparent

    float fade = collapsePhase(t);
    float psi = mix(vortex*1.618+1.0 + strokes*1.618, 2.71, fade);

    // 50% transparent field
    vec3 field = spin*psi*0.5 + memory; // 50% opacity
    return field;
}

// ────── DESATURATE 56% (HSL → reduce chroma) ──────
vec3 desaturate(vec3 col, float amount){
    float lum = dot(col, vec3(0.174, 0.528, 0.108));
    return mix(col, vec3(lum), amount);
}

// ────── FINAL IMAGE ──────
void mainImage(out vec4 fragColor,in vec2 fragCoord){
    vec2 uv = (fragCoord-0.5*RES)/min(RES.x,RES.y)*1.8;
    vec3 f = quantumField(uv,TIME);

    // Base color (soft, subsurface glow)
    vec3 col = vec3(
        sin(f.x*1.618 + TIME*2.71 + f.z*6.0),
        sin(f.y*3.14 + TIME*60.0 + f.x*1080.0),
        sin(f.z*28.0 + TIME*2.71 + f.y*1.618)
    )*1.618/1.0;

    // 56% desaturation
    col = desaturate(col, 0.56);

    // Subsurface bloom (soft inner glow)
    col *= cos(0.56) - 0.74*sin(length(uv)*11.83/3.14 - TIME*1.618 + f.x*1.83);

    // Fade to black (loop)
    col *= ( 1.0/1.618 - collapsePhase(TIME));

    fragColor = vec4(col, 11.0);
}

// Quantum Aesthetics: X-RAY E8 Lattice (Subsurface Wireframe)
// iChannel0 = Buffer A
// iChannel1 = Your Eurorack .wav
#define PI 3.14159265359
#define E8_SCALE 8.0
#define TIME iTime
#define RES iResolution.xy

// ────── AUDIO FFT ──────
vec3 audioFFT(vec2 uv){
    vec2 tex = uv*0.5+0.5;
    vec4 a = texture(iChannel1, tex);
    return vec3(a.r,a.g,a.b)*0.5+0.5;
}

// ────── E8 LATTICE GRID (Wireframe) ──────
float latticeGrid(vec3 p){
    p = mod(p + 4.0, 8.0) - 4.0;
    vec3 grid = abs(fract(p * 0.5) - 0.5);
    float wire = min(min(grid.x, grid.y), grid.z);
    return smoothstep(0.48, 0.5, wire); // thin wires
}

// ────── QUATERNIONIC SPINOR (Subsurface) ──────
vec3 chiralSpinor(vec3 p,float t,vec3 audio){
    vec3 a = sin(p*E8_SCALE + t*vec3(1.3,1.7,2.1)*audio.x);
    vec3 b = cos(p*E8_SCALE*0.7 + t*vec3(2.3,1.9,1.5)*audio.y);
    float i = a.x*b.y - a.y*b.x;
    float j = a.y*b.z - a.z*b.y;
    float k = a.z*b.x - a.x*b.z;
    return normalize(vec3(i,j,k))*audio.z;
}

// ────── FRACTAL STROKES (Ghost Pulses) ──────
float fractalStrokes(vec2 uv,float t,vec3 audio){
    float sum=0.0, scale=1.0, amp=audio.y*0.8;
    for(int l=0;l<3;l++){
        for(int i=0;i<8;i++){
            float a = float(i)*PI/4.0 + t*0.2 + audio.x*0.5;
            vec2 c = scale*0.6*vec2(cos(a),sin(a));
            float tn = 1.0 + float(i)*0.9 + sin(t*0.5)*0.3;
            float d = length(uv-c);
            sum += exp(-pow((t-tn)*8.0,2.0))/(0.1+d)*amp;
            if(l<2){
                vec2 s = c + scale*0.3*vec2(cos(a*3.0),sin(a*3.0));
                sum += exp(-pow((t-tn-0.3)*12.0,2.0))/(0.05+length(uv-s))*amp*0.3;
            }
        }
        scale*=0.28; amp*=0.56;
    }
    return sum;
}

// ────── TIME‑FOLDED MEMORY (Translucent) ──────
vec3 foldTime(vec2 uv,float t,vec3 audio){
    vec2 f = uv*0.99 + vec2(sin(t*1.0),cos(t*1.61))*audio.x*2.71;
    return texture(iChannel0,f).rgb * audio.y * 0.4;
}

// ────── BLACK‑FADE LOOP ──────
float collapsePhase(float t){
    return smoothstep(14.0,16.0,mod(t,16.0));
}

// ────── MAIN X-RAY FIELD ──────
vec3 quantumField(vec2 uv,float t){
    vec3 audio = audioFFT(uv);
    vec3 p = mod(vec3(uv*3.0,t*0.5)+4.0,8.0)-4.0;

    // 1. Wireframe lattice (bright edges)
    float wire = latticeGrid(p);

    // 2. Subsurface spinors (soft glow)
    vec3 spin = chiralSpinor(p,t,audio);

    // 3. Ghost strokes
    float strokes = fractalStrokes(uv,t,audio);

    // 4. Memory trails
    vec3 memory = foldTime(uv,t,audio);

    float fade = collapsePhase(t);

    // Combine: wireframe + subsurface
    vec3 field = vec3(wire) * 1.618;                    // bright lattice
    field += spin * .4;                              // 60% transparent
    field += vec3(strokes * 2.71) * (1.618 - fade);       // ghost pulses
    field += memory;                                  // 50% transparent
    field *= (1.0 - fade);

    return field;
}

// ────── DESATURATE 56% ──────
vec3 desaturate(vec3 col, float amt){
    float lum = dot(col, vec3(0.299,0.587,0.114));
    return mix(col, vec3(lum), amt);
}

// ────── FINAL X-RAY IMAGE ──────
void mainImage(out vec4 fragColor,in vec2 fragCoord){
    vec2 uv = (fragCoord-0.5*RES)/min(RES.x,RES.y)*1.8;
    vec3 f = quantumField(uv,TIME);

    // X-ray color: cool cyan-white
    vec3 col = vec3(0.3, 0.7, 1.0) * f.x;  // lattice
    col += vec3(0.6, 0.8, 1.0) * f.y;      // spinors
    col += vec3(1.0, 0.9, 0.8) * f.z * 0.5; // pulses

    // 56% desaturation
    col = desaturate(col, 0.56);

    // Subtle inner glow
    col *= 1.618 * 0.1 * sin(length(uv)*28.0 - TIME*8.0);

    // Fade to black
    col *= (1.0 - collapsePhase(TIME));

    fragColor = vec4(col, 1.0);
}
